// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Library: none — native interpolate/spring with SVG 3D extrusion

const { fontFamily: antonFamily } = loadAnton();



export type FinanceBrothersProps = Record<string, any>;

const FinanceBrothers: React.FC<FinanceBrothersProps> = ({
  line1Text = "FINANCE",
  line2Text = "BROTHERS",
  line1Color = "#ba3232",
  line1StrokeColor = "#ffffff",
  line2Color = "#ffffff",
  line2StrokeColor = "#ba3232",
  shadowColor = "#020a1c",
  backgroundColor = "#061d4d",
  transparentBackground = true,
  durationInSeconds = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 

  // Parser safety for transparent background logic
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Entrance animation: fast slam down from scale 3 to 1
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 11, stiffness: 90, mass: 1 },
  });
  
  const entranceScale = interpolate(entranceSpring, [0, 1], [3, 1], { extrapolateRight: "clamp" });
  const entranceOpacity = interpolate(frame, [0, 6], [0, 1], { extrapolateRight: "clamp" });

  // Exit animation: shrink and fade out in the last 20 frames
  const actualExitStart = Math.max(10, durationInFrames - 20);
  const actualExitEnd = Math.max(actualExitStart + 1, durationInFrames - 5);
  
  const exitSpring = spring({
    frame: Math.max(0, frame - actualExitStart),
    fps,
    config: { damping: 14, stiffness: 120 },
  });
  
  const exitScale = interpolate(exitSpring, [0, 1], [1, 0.8], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const exitOpacity = interpolate(frame, [actualExitStart, actualExitEnd], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Combine entrance and exit multipliers
  const currentScale = entranceScale * exitScale;
  const currentOpacity = entranceOpacity * exitOpacity;

  // Continuous subtle floating drift for the "overlay" feel
  const driftY = Math.sin(frame / 20) * 15 * s;
  const driftRot = Math.sin(frame / 30) * 1.5;
  
  const baseRotation = -4; // Classic poster angle tilt
  const finalRotation = baseRotation + driftRot;

  // 3D Shadow Configuration
  const strokeWidth = 18 * s;
  const depth = Math.floor(20 * s);
  const shadowDx = 0.4; // Drop angle X multiplier
  const shadowDy = 1.0; // Drop angle Y multiplier

  // Dynamic font sizing based on string length to roughly match block widths
  const getFontSize = (text: string) => {
    const len = Math.max(text.length, 3);
    const size = (2000 / len) * s;
    return Math.min(size, 350 * s); 
  };

  const fontSize1 = getFontSize(line1Text);
  const fontSize2 = getFontSize(line2Text);

  // Stack baselines tightly so the letters almost touch
  const baseline1 = 0;
  const capHeight2 = fontSize2 * 0.7; // Anton cap height ratio
  const gap = 5 * s;
  const baseline2 = baseline1 + capHeight2 + gap;

  // Center the entire block vertically inside the group
  const capHeight1 = fontSize1 * 0.7;
  const blockCenterY = (-capHeight1 + baseline2) / 2;

  // Reusable 3D Extrusion Text Renderer
  const renderTextWithExtrusion = (
    text: string, 
    yPos: number, 
    fontSize: number, 
    fillColor: string, 
    strokeCol: string
  ) => {
    return (
      <g transform={`translate(0, ${yPos})`} style={{ transition: "none" }}>
        {/* Render multiple layered instances to create a solid 3D extrusion shadow */}
        {Array.from({ length: depth }).map((_, i) => (
          <text
            key={`shadow-${i}`}
            x={(i + 1) * shadowDx}
            y={(i + 1) * shadowDy}
            textAnchor="middle"
            fontFamily={antonFamily}
            fontSize={fontSize}
            fill={shadowColor}
            stroke={shadowColor}
            strokeWidth={strokeWidth}
            strokeLinejoin="round"
            paintOrder="stroke fill"
            style={{ transition: "none" }}
          >
            {text}
          </text>
        ))}
        
        {/* Main Text Face */}
        <text
          x={0}
          y={0}
          textAnchor="middle"
          fontFamily={antonFamily}
          fontSize={fontSize}
          fill={fillColor}
          stroke={strokeCol}
          strokeWidth={strokeWidth}
          strokeLinejoin="round"
          paintOrder="stroke fill"
          style={{ transition: "none" }}
        >
          {text}
        </text>
      </g>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={{
        position: 'absolute',
        width: '100%',
        height: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        opacity: currentOpacity,
        transition: "none"
      }}>
        <svg 
          width={width} 
          height={height} 
          viewBox={`0 0 ${width} ${height}`}
          style={{ overflow: 'visible', transition: "none" }}
        >
          {/* Main Animated Group Container */}
          <g transform={`
            translate(${width / 2}, ${height / 2 + driftY}) 
            rotate(${finalRotation}) 
            scale(${currentScale})
          `} style={{ transition: "none" }}>
            
            <g transform={`translate(0, ${-blockCenterY})`} style={{ transition: "none" }}>
              {/* Line 1 renders first (behind Line 2) */}
              {renderTextWithExtrusion(line1Text, baseline1, fontSize1, line1Color, line1StrokeColor)}
              {/* Line 2 renders on top */}
              {renderTextWithExtrusion(line2Text, baseline2, fontSize2, line2Color, line2StrokeColor)}
            </g>

          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default FinanceBrothers;